<script setup lang="ts">
import {confirmAction} from '../ui/confirm'
import {ref} from 'vue'
import {request} from '../api'
import type {Life} from './types'
const props=defineProps<{recordId?:string;revision?:number;body?:string;value:Life;disabled:boolean}>()
const emit=defineEmits<{(e:'pending',value:boolean):void;(e:'synchronized',record:any):void}>()
const diff=ref<any>(null)
async function compare(){if(!props.recordId||busy.value)return;busy.value=true;error.value='';try{diff.value=await request('/admin/content/records/'+props.recordId+'/itinerary-sync-preview',{method:'POST',body:JSON.stringify({expected_revision:props.revision,body:props.body})})}catch(e){error.value=String(e)}finally{busy.value=false}}
async function reconcile(){if(!diff.value||busy.value||!await confirmAction('按预览同步自动行程？人工活动和人工修改会保留；移除的自动活动仍保留历史，不删除地点或照片。'))return;busy.value=true;emit('pending',true);error.value='';let updated:any;try{updated=await request('/admin/content/records/'+props.recordId+'/itinerary-sync-confirm',{method:'POST',body:JSON.stringify({expected_revision:diff.value.revision,body_hash:diff.value.body_hash})});diff.value=null}catch(e){error.value=String(e)}finally{busy.value=false;emit('pending',false)}if(updated)emit('synchronized',updated)}
const result=ref<any>(null),selected=ref<string[]>([]),busy=ref(false),error=ref(''),notice=ref('')
async function preview(){if(!props.recordId||busy.value)return;busy.value=true;error.value='';notice.value='';try{result.value=await request('/admin/content/records/'+props.recordId+'/itinerary-preview',{method:'POST',body:JSON.stringify({expected_revision:props.revision,body:props.body})});selected.value=result.value.items.map((x:any)=>x.source_key)}catch(e){error.value=String(e)}finally{busy.value=false}}
async function append(){if(!result.value||!selected.value.length||busy.value||!await confirmAction('只追加勾选的活动到编辑草稿，不覆盖手动行程、地点或照片。随后使用文章保存提交。继续吗？'))return;busy.value=true;error.value='';try{const data=await request('/admin/content/records/'+props.recordId+'/itinerary-confirm',{method:'POST',body:JSON.stringify({expected_revision:result.value.revision,body:props.body,body_hash:result.value.body_hash,selected:selected.value})});const keys=new Set(props.value.activities.map(a=>a.source_key));const added=data.items.filter((x:any)=>!keys.has(x.source_key));if(props.value.activities.length+added.length>300)throw Error('超过300项上限，请减少所选活动');props.value.activities.push(...added);notice.value='已追加 '+added.length+' 项到编辑草稿，请保存；没有修改手动活动。';result.value=null}catch(e){error.value=String(e)}finally{busy.value=false}}
</script>
<template><section class="itinerary-extract"><h4>从正文提取行程（离线规则）</h4><p>首次发布会尝试生成行程；再次保存不会覆盖行程。先保存正文及旅行日期，再提取。支持YYYY-MM-DD、中文日期、时间和“第N天”；不会猜测地点和照片，不会自动覆盖或发布。</p><button type="button" class="quiet" :disabled="disabled||busy||!recordId" @click="compare">预览完整行程差异</button><section v-if="diff" aria-label="行程同步差异"><h4>确认前核对变化</h4><p v-for="change in diff.changes" :key="change.operation+change.item.id">{{({add:'新增',remove:'移除自动活动',update:'更新自动活动',reorder:'调整自动活动顺序'} as Record<string,string>)[change.operation]}} · {{change.item.day}} · {{change.item.title}}</p><p v-for="item in diff.preserved" :key="item.id">保留人工活动 · {{item.day}} · {{item.title}}</p><p v-for="conflict in diff.conflicts||[]" :key="conflict.id" role="status">冲突（保留人工版本） · {{conflict.title}} · {{conflict.message}}</p><p v-if="!diff.changes.length">没有自动活动变化。</p><p v-for="warning in diff.warnings" :key="warning.line">第{{warning.line}}行：{{warning.message}}</p><button type="button" :disabled="disabled||busy" @click="reconcile">确认同步以上差异</button><button type="button" class="quiet" :disabled="busy" @click="diff=null">取消差异预览</button></section><p v-if="!recordId">首次保存草稿后可使用提取。</p><button type="button" class="quiet" :disabled="disabled||busy||!recordId" @click="preview">提取并预览行程</button><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><section v-if="result"><p v-for="(w,i) in result.warnings" :key="i">第{{w.line}}行：{{w.message}}</p><label v-for="item in result.items" :key="item.source_key" class="checks"><input v-model="selected" type="checkbox" :value="item.source_key" :disabled="disabled||busy"/>{{item.day}} {{item.time||'时间未定'}} · {{item.title}}（第{{item.line}}行）</label><p v-if="!result.items.length">没有新的可提取活动，已同步的活动不会重复追加。</p><button type="button" :disabled="disabled||busy||!selected.length" @click="append">确认追加所选活动到草稿</button><button type="button" class="quiet" :disabled="busy" @click="result=null">取消预览</button></section></section></template>
<style scoped>.itinerary-extract{margin:20px 0;padding:16px;border:1px solid var(--line);border-radius:var(--radius)}.checks{display:flex;align-items:start;gap:10px;overflow-wrap:anywhere}.checks input{width:auto;flex:none}</style>
